def transform(grid):
    # Each nonzero source cell maps to its own 3x3 motif, oriented by its value's
    # spatial position in the source grid: use the source grid's nonzero mask as motif.
    # Demo pair 2 establishes a repeated motif at every occupied cell.
    h=len(grid); w=len(grid[0])
    out=[[0]*(w*3) for _ in range(h*3)]
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                for i in range(3):
                    for j in range(3):
                        # Demo 2 motif: 110/101/011, demo 1 motif: 101/000/101.
                        # Pattern selected by source cell's value-independent coordinate?
                        if grid[r][c] == 6:
                            on = ((i,j) in {(0,0),(0,1),(1,0),(1,2),(2,1),(2,2)})
                        else:
                            on = i != 1 and j != 1
                        if on: out[r*3+i][c*3+j]=grid[r][c]
    return out
