def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * (3 * w) for _ in range(3 * h)]
    # The 3x3 stamp is the complement of the input's nonzero mask.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                for i in range(3):
                    for j in range(3):
                        if grid[i][j] == 0:
                            out[3 * r + i][3 * c + j] = grid[r][c]
    return out
